args.new_string:
interface UserProfileData {
  name: string
  email: string
}

async function getUserProfile(): Promise<UserProfileData | null> {
  try {
    const res = await fetch('/api/users/profile')
    if (!res.ok) return null
    return (await res.json()) as UserProfileData
  } catch {
    return null
  }
}

export default async function UserProfile() {
  const user = await getUserProfile()

  return (
    <div>
      <h2>User Profile</h2>
      {user ? (
        <div>
          <div>{user.name}</div>
          <div>{user.email}</div>
        </div>
      ) : (
        <div>User profile unavailable</div>
      )}
    </div>
  )
}

